    FIELD_9 = 1001,
    FIELD_10 = '2694015871'
WHERE FIELD_9 = 1011
    AND IDENTITYID IN (
        SELECT bo.BIZ_ORG_ID
        FROM CPSMGT.CPS_BIZ_ORG bo
        WHERE bo.SHORT_CODE = 'AG4015871'
            AND bo.STATUS = 03
    );

